import{_ as a,c as t,o as i,j as n,Y as o,t as l}from"./chunks/framework.BNTND4LZ.js";const y=JSON.parse('{"title":"hosts.equiv | x-cmd man (man5) | list of hosts and users that are granted \\\\\\"trusted\\\\\\" **r**","titleTemplate":false,"description":"x-cmd man (man5 Manual Page) | hosts.equiv - list of hosts and users that are granted \\\\\\"trusted\\\\\\" **r**","frontmatter":{"pageClass":"x-man","head":[["meta",{"name":"og:title","content":"hosts.equiv | x-cmd man (man5) | list of hosts and users that are granted \\\\\\"trusted\\\\\\" **r**"}],["meta",{"name":"og:description","content":"x-cmd man (man5 Manual Page) | hosts.equiv - list of hosts and users that are granted \\\\\\"trusted\\\\\\" **r**"}]]},"headers":[],"params":{"isMan":true,"man":"hosts.equiv","category":"man5","desc":"list of hosts and users that are granted \\\\\\"trusted\\\\\\" **r**"},"relativePath":"man5/hosts.equiv.md","filePath":"man5/[man].md"}'),h={name:"man5/hosts.equiv.md"},r={class:"visually-hidden"};function p(e,s,d,c,u,m){return i(),t("div",null,[n("h1",r,l(e.$params.man),1),s[0]||(s[0]=o(`<h2 id="name" tabindex="-1">NAME <a class="header-anchor" href="#name" aria-label="Permalink to &quot;NAME&quot;">​</a></h2><p>hosts.equiv - list of hosts and users that are granted &quot;trusted&quot; <strong>r</strong> command access to your system</p><h2 id="description" tabindex="-1">DESCRIPTION <a class="header-anchor" href="#description" aria-label="Permalink to &quot;DESCRIPTION&quot;">​</a></h2><p>The file <em>/etc/hosts.equiv</em> allows or denies hosts and users to use the <strong>r</strong>-commands (e.g., <strong>rlogin</strong>, <strong>rsh</strong>, or <strong>rcp</strong>) without supplying a password.</p><p>The file uses the following format:</p><p><em>+|[-]hostname|+@netgroup|-@netgroup</em> <em>[+|[-]username|+@netgroup|-@netgroup]</em></p><p>:</p><p>The <em>hostname</em> is the name of a host which is logically equivalent to the local host. Users logged into that host are allowed to access like-named user accounts on the local host without supplying a password. The <em>hostname</em> may be (optionally) preceded by a plus (+) sign. If the plus sign is used alone, it allows any host to access your system. You can explicitly deny access to a host by preceding the <em>hostname</em> by a minus (-) sign. Users from that host must always supply additional credentials, including possibly a password. For security reasons you should always use the FQDN of the hostname and not the short hostname.</p><p>The <em>username</em> entry grants a specific user access to all user accounts (except root) without supplying a password. That means the user is NOT restricted to like-named accounts. The <em>username</em> may be (optionally) preceded by a plus (+) sign. You can also explicitly deny access to a specific user by preceding the <em>username</em> with a minus (-) sign. This says that the user is not trusted no matter what other entries for that host exist.</p><p>Netgroups can be specified by preceding the netgroup by an @ sign.</p><p>Be extremely careful when using the plus (+) sign. A simple typographical error could result in a standalone plus sign. A standalone plus sign is a wildcard character that means &quot;any host&quot;!</p><h2 id="files" tabindex="-1">FILES <a class="header-anchor" href="#files" aria-label="Permalink to &quot;FILES&quot;">​</a></h2><p><em>/etc/hosts.equiv</em></p><h2 id="notes" tabindex="-1">NOTES <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;NOTES&quot;">​</a></h2><p>Some systems will honor the contents of this file only when it has owner root and no write permission for anybody else. Some exceptionally paranoid systems even require that there be no other hard links to the file.</p><p>Modern systems use the Pluggable Authentication Modules library (PAM). With PAM a standalone plus sign is considered a wildcard character which means &quot;any host&quot; only when the word <em>promiscuous</em> is added to the auth component line in your PAM file for the particular service (e.g., <strong>rlogin</strong>).</p><h2 id="examples" tabindex="-1">EXAMPLES <a class="header-anchor" href="#examples" aria-label="Permalink to &quot;EXAMPLES&quot;">​</a></h2><p>Below are some example <em>/etc/host.equiv</em> or <em>~/.rhosts</em> files.</p><p>Allow any user to log in from any host:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">+</span></span></code></pre></div><p>Allow any user from <em>host</em> with a matching local account to log in:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">host</span></span></code></pre></div><p>Note: the use of <em>+host</em> is never a valid syntax, including attempting to specify that any user from the host is allowed.</p><p>Allow any user from <em>host</em> to log in:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">host</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> +</span></span></code></pre></div><p>Note: this is distinct from the previous example since it does not require a matching local account.</p><p>Allow <em>user</em> from <em>host</em> to log in as any non-root user:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">host</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> user</span></span></code></pre></div><p>Allow all users with matching local accounts from <em>host</em> to log in except for <em>baduser</em>:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">host</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -baduser</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">host</span></span></code></pre></div><p>Deny all users from <em>host</em>:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">-host</span></span></code></pre></div><p>Note: the use of <em>-host -user</em> is never a valid syntax, including attempting to specify that a particular user from the host is not trusted.</p><p>Allow all users with matching local accounts on all hosts in a <em>netgroup</em>:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">+@netgroup</span></span></code></pre></div><p>Disallow all users on all hosts in a <em>netgroup</em>:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">-@netgroup</span></span></code></pre></div><p>Allow all users in a <em>netgroup</em> to log in from <em>host</em> as any non-root user:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">host</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> +@netgroup</span></span></code></pre></div><p>Allow all users with matching local accounts on all hosts in a <em>netgroup</em> except <em>baduser</em>:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">+@netgroup</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -baduser</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">+@netgroup</span></span></code></pre></div><p>Note: the deny statements must always precede the allow statements because the file is processed sequentially until the first matching rule is found.</p><h2 id="see-also" tabindex="-1">SEE ALSO <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;SEE ALSO&quot;">​</a></h2><p><strong>rhosts</strong>(5), <strong>rlogind</strong>(8), <strong>rshd</strong>(8)</p>`,44))])}const k=a(h,[["render",p]]);export{y as __pageData,k as default};
